<?php
namespace App\Models;use Illuminate\Database\Eloquent\{Builder,Model};
class TransportSchedule extends Model{protected $fillable=['company_id','transport_route_id','name','starts_on','ends_on','default_start_time','default_arrival_time','arrival_next_day','service_type','shift','vehicle_id','driver_id','monitor_id','status','created_by','updated_by'];protected $casts=['starts_on'=>'date','ends_on'=>'date','arrival_next_day'=>'boolean'];public function scopeForCompany(Builder$q,int$id):Builder{return$q->where('company_id',$id);}public function route(){return$this->belongsTo(TransportRoute::class,'transport_route_id');}public function days(){return$this->hasMany(TransportScheduleDay::class);}public function vehicle(){return$this->belongsTo(TransportVehicle::class);}public function driver(){return$this->belongsTo(TransportPerson::class);}public function monitor(){return$this->belongsTo(TransportPerson::class);}public function services(){return$this->hasMany(TransportService::class);}}
